#!/usr/bin/env python3
"""Bidirectional Key-Segment stream engine.

Entry point for the two executables described by the task:

``main.py compile``
    Read one UTF-8 JSON configuration from stdin through EOF, validate it and
    write one JSON object describing the compiled program to stdout.  An
    invalid configuration yields ``{"error":"config"}`` and exit status 2.

``main.py stream /absolute/path/program.json``
    Load a compiled program and serve the line oriented request/response
    protocol.  Every request produces exactly one response line which is
    flushed before the next request is read.  A fatal request error yields
    ``{"error":"event"}`` and exit status 2.

Only the Python standard library is used.

Design notes
------------
* Rule matching uses a packed Shift-And automaton.  Every rule owns a block of
  ``maxlen + 1`` bits inside one big integer; bit ``p`` of a rule block means
  "the last ``p + 1`` features match the first ``p + 1`` positions of that
  rule".  A single update per packet therefore tests *all* rules at once.
* The per value masks are produced by an XOR sweep over the range endpoints,
  which keeps building the masks cheap (one sweep over the value domain).
* Only bounded per flow state is retained: the automaton state, the first
  ``prefix_width`` features (needed by the backup tree) and the last
  ``maxlen`` features (enough to rebuild the automaton state after a restart).
"""

import heapq
import json
import sys

sys.set_int_max_str_digits(8192)

# ---------------------------------------------------------------------------
# constants
# ---------------------------------------------------------------------------

MAX_FLOWS = 4096
MAX_RULES = 2048
MAX_RANGES_PER_RULE = 32
MAX_TOTAL_POSITIONS = 16384
MAX_TREE_NODES = 255
MAX_TREE_DEPTH = 16
VALUE_OFFSET = 2048
VALUE_COUNT = 4097          # signed features live in [-2048, 2048]
MAX_LENGTH = 2048

CONFIG_KEYS = frozenset(
    ("version", "idle_timeout", "packet_limit", "prefix_width", "rules", "fallback")
)

REQUEST_KEYS = {
    "open": frozenset(("op", "flow", "time")),
    "chunk": frozenset(("op", "packets")),
    "tick": frozenset(("op", "time")),
    "close": frozenset(("op", "flow", "time")),
    "checkpoint": frozenset(("op",)),
    "restore": frozenset(("op", "checkpoint")),
}

PACKET_KEYS = frozenset(("flow", "time", "source", "length"))

FLOW_ID_MAX = 2 ** 31 - 1
TIME_MAX = 2 ** 53 - 1


class Fatal(Exception):
    """Raised for any request that must produce {"error":"event"}."""


# ---------------------------------------------------------------------------
# strict JSON helpers
# ---------------------------------------------------------------------------


def _pairs_hook(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError("duplicate object key")
        obj[key] = value
    return obj


def _reject_constant(name):
    raise ValueError("non finite JSON constant: %s" % (name,))


def strict_loads(text):
    """Parse JSON rejecting duplicate keys and NaN/Infinity."""
    return json.loads(
        text, object_pairs_hook=_pairs_hook, parse_constant=_reject_constant
    )


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _int_in(value, low, high):
    return _is_int(value) and low <= value <= high


# ---------------------------------------------------------------------------
# configuration validation
# ---------------------------------------------------------------------------


def _validate_tree(node, width, depth, counter):
    """Validate one fallback tree node; returns the normalised node or None."""
    if depth > MAX_TREE_DEPTH:
        return None
    if not isinstance(node, dict):
        return None
    keys = frozenset(node.keys())
    if keys == frozenset(("class",)):
        klass = node["class"]
        if not _int_in(klass, 0, 65535):
            return None
        counter[0] += 1
        if counter[0] > MAX_TREE_NODES:
            return None
        return {"class": klass}
    if keys == frozenset(("feature", "threshold", "le", "gt")):
        if depth + 1 > MAX_TREE_DEPTH:
            # children would sit one edge below the allowed root-to-leaf depth
            return None
        feature = node["feature"]
        threshold = node["threshold"]
        if not _int_in(feature, 0, width - 1):
            return None
        if not _int_in(threshold, -MAX_LENGTH, MAX_LENGTH):
            return None
        counter[0] += 1
        if counter[0] > MAX_TREE_NODES:
            return None
        le = _validate_tree(node["le"], width, depth + 1, counter)
        if le is None:
            return None
        gt = _validate_tree(node["gt"], width, depth + 1, counter)
        if gt is None:
            return None
        return {
            "feature": feature,
            "threshold": threshold,
            "le": le,
            "gt": gt,
        }
    return None


def validate_config(config):
    """Return a normalised configuration or None when the config is invalid."""
    if not isinstance(config, dict):
        return None
    if frozenset(config.keys()) != CONFIG_KEYS:
        return None

    version = config["version"]
    if not _is_int(version) or version != 1:
        return None

    idle_timeout = config["idle_timeout"]
    if not _int_in(idle_timeout, 0, 10 ** 9):
        return None

    packet_limit = config["packet_limit"]
    if not _int_in(packet_limit, 1, 10 ** 9):
        return None

    width = config["prefix_width"]
    if not _int_in(width, 1, 32):
        return None

    rules_in = config["rules"]
    if not isinstance(rules_in, list) or len(rules_in) > MAX_RULES:
        return None

    seen_ids = set()
    total_positions = 0
    rules = []
    for rule in rules_in:
        if not isinstance(rule, dict):
            return None
        if frozenset(rule.keys()) != frozenset(("id", "class", "priority", "ranges")):
            return None
        rule_id = rule["id"]
        rule_class = rule["class"]
        priority = rule["priority"]
        ranges_in = rule["ranges"]
        if not _int_in(rule_id, 0, FLOW_ID_MAX) or rule_id in seen_ids:
            return None
        seen_ids.add(rule_id)
        if not _int_in(rule_class, 0, 65535):
            return None
        if not _int_in(priority, -2 ** 31, 2 ** 31 - 1):
            return None
        if not isinstance(ranges_in, list):
            return None
        if not 1 <= len(ranges_in) <= MAX_RANGES_PER_RULE:
            return None
        ranges = []
        for span in ranges_in:
            if not isinstance(span, list) or len(span) != 2:
                return None
            low, high = span
            if not _is_int(low) or not _is_int(high):
                return None
            if not (-MAX_LENGTH <= low <= high <= MAX_LENGTH):
                return None
            ranges.append([low, high])
        total_positions += len(ranges)
        if total_positions > MAX_TOTAL_POSITIONS:
            return None
        rules.append(
            {
                "id": rule_id,
                "class": rule_class,
                "priority": priority,
                "ranges": ranges,
            }
        )

    counter = [0]
    tree = _validate_tree(config["fallback"], width, 0, counter)
    if tree is None:
        return None

    return {
        "idle_timeout": idle_timeout,
        "packet_limit": packet_limit,
        "prefix_width": width,
        "rules": rules,
        "fallback": tree,
    }


def compile_config(config):
    """Validate and normalise a configuration into a compiled program."""
    normalised = validate_config(config)
    if normalised is None:
        return None
    program = {"v": 1}
    program.update(normalised)
    return program


# ---------------------------------------------------------------------------
# matcher
# ---------------------------------------------------------------------------


class Matcher:
    """Packed Shift-And automaton over all rules of a compiled program."""

    __slots__ = (
        "rules",
        "rule_ids",
        "maxlen",
        "block",
        "start",
        "match_mask",
        "masks",
    )

    def __init__(self, rules):
        # rules are stored sorted by id so that matches are emitted in
        # ascending rule id order.
        self.rules = sorted(rules, key=lambda r: r["id"])
        self.rule_ids = [r["id"] for r in self.rules]
        maxlen = 0
        for rule in self.rules:
            span = len(rule["ranges"])
            if span > maxlen:
                maxlen = span
        self.maxlen = maxlen
        self.block = maxlen + 1
        start = 0
        match_mask = 0
        events = {}
        for index, rule in enumerate(self.rules):
            offset = index * self.block
            start |= 1 << offset
            match_mask |= 1 << (offset + len(rule["ranges"]) - 1)
            for position, span in enumerate(rule["ranges"]):
                low, high = span
                bit = 1 << (offset + position)
                first = low + VALUE_OFFSET
                stop = high + 1 + VALUE_OFFSET
                events[first] = events.get(first, 0) ^ bit
                if stop < VALUE_COUNT:
                    events[stop] = events.get(stop, 0) ^ bit
        self.start = start
        self.match_mask = match_mask
        masks = [0] * VALUE_COUNT
        current = 0
        for index in range(VALUE_COUNT):
            toggle = events.get(index)
            if toggle is not None:
                current ^= toggle
            masks[index] = current
        self.masks = masks

    def step(self, state, feature):
        """Advance the automaton; returns (new_state, matched rule indices)."""
        new_state = ((state << 1) | self.start) & self.masks[feature + VALUE_OFFSET]
        bits = new_state & self.match_mask
        matched = []
        while bits:
            low = bits & -bits
            matched.append((low.bit_length() - 1) // self.block)
            bits ^= low
        return new_state, matched

    def replay(self, features):
        """Rebuild an automaton state from a bounded feature history."""
        state = 0
        masks = self.masks
        start = self.start
        for feature in features:
            state = ((state << 1) | start) & masks[feature + VALUE_OFFSET]
        return state


# ---------------------------------------------------------------------------
# per flow state
# ---------------------------------------------------------------------------


class Flow:
    __slots__ = (
        "src",
        "n",
        "last_act",
        "cls",
        "reason",
        "rule",
        "at",
        "dtime",
        "matches",
        "prefix",
        "tail",
        "state",
    )

    def __init__(self):
        self.src = None
        self.n = 0
        self.last_act = 0
        self.cls = None
        self.reason = None
        self.rule = None
        self.at = 0
        self.dtime = 0
        self.matches = 0
        self.prefix = []
        self.tail = []
        self.state = 0


# ---------------------------------------------------------------------------
# stream engine
# ---------------------------------------------------------------------------


class Engine:
    """Executes the request/response protocol against a compiled program."""

    def __init__(self, program):
        if not isinstance(program, dict):
            raise ValueError("program must be an object")
        self.idle_timeout = program["idle_timeout"]
        self.packet_limit = program["packet_limit"]
        self.width = program["prefix_width"]
        self.tree = program["fallback"]
        rules = program.get("rules") or []
        self.matcher = Matcher(rules) if rules else None
        self.maxlen = self.matcher.maxlen if self.matcher is not None else 0
        self.flows = {}
        self.idle_heap = []
        self.last_time = 0

    # -- helpers ----------------------------------------------------------

    def _eval_tree(self, flow):
        node = self.tree
        prefix = flow.prefix
        while True:
            if "class" in node:
                return node["class"]
            feature = node["feature"]
            threshold = node["threshold"]
            if feature < len(prefix):
                value = prefix[feature]
            else:
                value = 0
            node = node["le"] if value <= threshold else node["gt"]

    def _compact_heap(self):
        self.idle_heap = [
            (flow.last_act, fid)
            for fid, flow in self.flows.items()
            if flow.cls is None
        ]
        heapq.heapify(self.idle_heap)

    def _expire(self, now, events):
        """Emit idle decisions for every undecided flow that timed out."""
        heap = self.idle_heap
        if not heap:
            return
        limit = now - self.idle_timeout - 1
        if heap[0][0] > limit:
            return
        due = set()
        while heap and heap[0][0] <= limit:
            last_act, fid = heapq.heappop(heap)
            flow = self.flows.get(fid)
            if flow is None or flow.cls is not None or flow.last_act != last_act:
                continue
            due.add(fid)
        if not due:
            return
        for fid in sorted(due):
            flow = self.flows[fid]
            klass = self._eval_tree(flow)
            flow.cls = klass
            flow.reason = "idle"
            flow.rule = None
            flow.at = flow.n
            flow.dtime = now
            events.append(
                {
                    "type": "decision",
                    "flow": fid,
                    "class": klass,
                    "reason": "idle",
                    "at": flow.n,
                    "time": now,
                    "rule": None,
                }
            )

    # -- request handling -------------------------------------------------

    def handle(self, request, first):
        if not isinstance(request, dict):
            raise Fatal()
        op = request.get("op")
        if not isinstance(op, str):
            raise Fatal()
        expected = REQUEST_KEYS.get(op)
        if expected is None or frozenset(request.keys()) != expected:
            raise Fatal()
        if op == "restore":
            if not first:
                raise Fatal()
            return self._restore(request["checkpoint"])
        if op == "checkpoint":
            return {"checkpoint": self._checkpoint()}
        if op == "open":
            return self._open(request)
        if op == "tick":
            return self._tick(request)
        if op == "close":
            return self._close(request)
        return self._chunk(request)

    def _open(self, request):
        fid = request["flow"]
        now = request["time"]
        if not _int_in(fid, 0, FLOW_ID_MAX):
            raise Fatal()
        if not _int_in(now, 0, TIME_MAX):
            raise Fatal()
        if now < self.last_time:
            raise Fatal()
        if fid in self.flows:
            raise Fatal()
        if len(self.flows) >= MAX_FLOWS:
            raise Fatal()
        events = []
        self._expire(now, events)
        self.last_time = now
        flow = Flow()
        flow.last_act = now
        self.flows[fid] = flow
        heapq.heappush(self.idle_heap, (now, fid))
        return {"events": events}

    def _tick(self, request):
        now = request["time"]
        if not _int_in(now, 0, TIME_MAX):
            raise Fatal()
        if now < self.last_time:
            raise Fatal()
        events = []
        self._expire(now, events)
        self.last_time = now
        return {"events": events}

    def _close(self, request):
        fid = request["flow"]
        now = request["time"]
        if not _int_in(fid, 0, FLOW_ID_MAX):
            raise Fatal()
        if not _int_in(now, 0, TIME_MAX):
            raise Fatal()
        if now < self.last_time:
            raise Fatal()
        if fid not in self.flows:
            raise Fatal()
        events = []
        self._expire(now, events)
        self.last_time = now
        flow = self.flows[fid]
        if flow.cls is None:
            klass = self._eval_tree(flow)
            flow.cls = klass
            flow.reason = "end"
            flow.rule = None
            flow.at = flow.n
            flow.dtime = now
            events.append(
                {
                    "type": "decision",
                    "flow": fid,
                    "class": klass,
                    "reason": "end",
                    "at": flow.n,
                    "time": now,
                    "rule": None,
                }
            )
        events.append(
            {
                "type": "closed",
                "flow": fid,
                "packets": flow.n,
                "matches": flow.matches,
                "class": flow.cls,
                "reason": flow.reason,
                "rule": flow.rule,
            }
        )
        del self.flows[fid]
        return {"events": events}

    def _chunk(self, request):
        packets = request["packets"]
        if not isinstance(packets, list):
            raise Fatal()
        records = []
        previous = self.last_time
        for packet in packets:
            if not isinstance(packet, dict):
                raise Fatal()
            if frozenset(packet.keys()) != PACKET_KEYS:
                raise Fatal()
            fid = packet["flow"]
            now = packet["time"]
            source = packet["source"]
            length = packet["length"]
            if not _int_in(fid, 0, FLOW_ID_MAX):
                raise Fatal()
            if not _int_in(now, 0, TIME_MAX):
                raise Fatal()
            if not _int_in(source, 0, 1):
                raise Fatal()
            if not _int_in(length, 1, MAX_LENGTH):
                raise Fatal()
            if now < previous:
                raise Fatal()
            if fid not in self.flows:
                raise Fatal()
            previous = now
            records.append((fid, now, source, length))
        events = []
        for fid, now, source, length in records:
            self._expire(now, events)
            self.last_time = now
            self._packet(fid, now, source, length, events)
        return {"events": events}

    def _packet(self, fid, now, source, length, events):
        flow = self.flows[fid]
        if flow.src is None:
            flow.src = source
            feature = length
        else:
            feature = length if source == flow.src else -length
        flow.n += 1
        flow.last_act = now
        if flow.cls is None:
            heapq.heappush(self.idle_heap, (now, fid))
            if len(self.idle_heap) > 4 * len(self.flows) + 64:
                self._compact_heap()

        matcher = self.matcher
        matched = []
        if matcher is not None:
            flow.state = ((flow.state << 1) | matcher.start) & matcher.masks[
                feature + VALUE_OFFSET
            ]
            bits = flow.state & matcher.match_mask
            while bits:
                low = bits & -bits
                matched.append((low.bit_length() - 1) // matcher.block)
                bits ^= low
        else:
            flow.state = 0

        for index in matched:
            rule = matcher.rules[index]
            span = len(rule["ranges"])
            flow.matches += 1
            events.append(
                {
                    "type": "match",
                    "flow": fid,
                    "rule": rule["id"],
                    "start": flow.n - span,
                    "end": flow.n,
                }
            )

        if len(flow.prefix) < self.width:
            flow.prefix.append(feature)
        if self.maxlen:
            flow.tail.append(feature)
            if len(flow.tail) > self.maxlen:
                del flow.tail[0]

        if flow.cls is not None:
            return
        if matched:
            best = None
            best_key = None
            for index in matched:
                rule = matcher.rules[index]
                key = (-rule["priority"], -len(rule["ranges"]), rule["id"])
                if best_key is None or key < best_key:
                    best_key = key
                    best = rule
            flow.cls = best["class"]
            flow.reason = "key"
            flow.rule = best["id"]
            flow.at = flow.n
            flow.dtime = now
            events.append(
                {
                    "type": "decision",
                    "flow": fid,
                    "class": best["class"],
                    "reason": "key",
                    "at": flow.n,
                    "time": now,
                    "rule": best["id"],
                }
            )
        elif flow.n >= self.packet_limit:
            klass = self._eval_tree(flow)
            flow.cls = klass
            flow.reason = "packet_limit"
            flow.rule = None
            flow.at = flow.n
            flow.dtime = now
            events.append(
                {
                    "type": "decision",
                    "flow": fid,
                    "class": klass,
                    "reason": "packet_limit",
                    "at": flow.n,
                    "time": now,
                    "rule": None,
                }
            )

    # -- checkpointing ----------------------------------------------------

    def _checkpoint(self):
        flows = []
        for fid, flow in self.flows.items():
            decision = None
            if flow.cls is not None:
                decision = [
                    flow.cls,
                    flow.reason,
                    flow.rule,
                    flow.at,
                    flow.dtime,
                ]
            flows.append(
                {
                    "f": fid,
                    "s": flow.src,
                    "n": flow.n,
                    "a": flow.last_act,
                    "d": decision,
                    "m": flow.matches,
                    "p": list(flow.prefix),
                    "g": list(flow.tail),
                }
            )
        return {"v": 1, "t": self.last_time, "fl": flows}

    def _restore(self, value):
        if not isinstance(value, dict):
            raise Fatal()
        try:
            if value.get("v") != 1:
                raise Fatal()
            now = value.get("t")
            records = value.get("fl")
            if not isinstance(records, list):
                raise Fatal()
            if not _int_in(now, 0, TIME_MAX):
                raise Fatal()
            flows = {}
            for record in records:
                if not isinstance(record, dict):
                    raise Fatal()
                fid = record["f"]
                src = record["s"]
                count = record["n"]
                last_act = record["a"]
                decision = record["d"]
                matches = record["m"]
                prefix = record["p"]
                tail = record["g"]
                if not _int_in(fid, 0, FLOW_ID_MAX):
                    raise Fatal()
                if src is not None and not _int_in(src, 0, 1):
                    raise Fatal()
                if not _int_in(count, 0, 10 ** 9):
                    raise Fatal()
                if not _int_in(last_act, 0, TIME_MAX):
                    raise Fatal()
                if not _int_in(matches, 0, 10 ** 9):
                    raise Fatal()
                if not isinstance(prefix, list) or not isinstance(tail, list):
                    raise Fatal()
                if len(prefix) > self.width or len(tail) > self.maxlen:
                    raise Fatal()
                flow = Flow()
                flow.src = src
                flow.n = count
                flow.last_act = last_act
                flow.matches = matches
                for feature in prefix:
                    if not _int_in(feature, -MAX_LENGTH, MAX_LENGTH):
                        raise Fatal()
                for feature in tail:
                    if not _int_in(feature, -MAX_LENGTH, MAX_LENGTH):
                        raise Fatal()
                flow.prefix = list(prefix)
                flow.tail = list(tail)
                if decision is not None:
                    if (
                        not isinstance(decision, list)
                        or len(decision) != 5
                        or not _int_in(decision[0], 0, 65535)
                        or decision[1] not in ("key", "idle", "packet_limit", "end")
                    ):
                        raise Fatal()
                    if decision[2] is not None and not _int_in(decision[2], 0, FLOW_ID_MAX):
                        raise Fatal()
                    if not _int_in(decision[3], 0, 10 ** 9):
                        raise Fatal()
                    if not _int_in(decision[4], 0, TIME_MAX):
                        raise Fatal()
                    flow.cls = decision[0]
                    flow.reason = decision[1]
                    flow.rule = decision[2]
                    flow.at = decision[3]
                    flow.dtime = decision[4]
                if self.matcher is not None:
                    flow.state = self.matcher.replay(flow.tail)
                flows[fid] = flow
        except Fatal:
            raise
        except Exception:
            raise Fatal()
        self.flows = flows
        self.last_time = now
        self.idle_heap = [
            (flow.last_act, fid)
            for fid, flow in flows.items()
            if flow.cls is None
        ]
        heapq.heapify(self.idle_heap)
        return {"events": []}


# ---------------------------------------------------------------------------
# process entry points
# ---------------------------------------------------------------------------


def run_compile():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        raw = b""
    try:
        text = raw.decode("utf-8")
        config = strict_loads(text)
    except Exception:
        config = None
    program = None
    if config is not None:
        try:
            program = compile_config(config)
        except Exception:
            program = None
    if program is None:
        sys.stdout.write('{"error":"config"}\n')
        sys.stdout.flush()
        return 2
    sys.stdout.write(json.dumps(program, separators=(",", ":"), ensure_ascii=True))
    sys.stdout.write("\n")
    sys.stdout.flush()
    return 0


def run_stream(path):
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
        program = strict_loads(raw.decode("utf-8"))
        engine = Engine(program)
    except Exception:
        sys.stdout.write('{"error":"event"}\n')
        sys.stdout.flush()
        return 2

    stdin = sys.stdin.buffer
    out = sys.stdout
    first = True
    while True:
        line = stdin.readline()
        if not line:
            break
        try:
            request = strict_loads(line.decode("utf-8"))
        except Exception:
            out.write('{"error":"event"}\n')
            out.flush()
            return 2
        try:
            response = engine.handle(request, first)
        except Fatal:
            out.write('{"error":"event"}\n')
            out.flush()
            return 2
        except Exception:
            out.write('{"error":"event"}\n')
            out.flush()
            return 2
        first = False
        out.write(json.dumps(response, separators=(",", ":"), ensure_ascii=True))
        out.write("\n")
        out.flush()
    return 0


# ---------------------------------------------------------------------------
